// AP Physics 1 review, Unit 8: Fluids (8.1 to 8.4). 38 multiple choice, one EDA and one QQT free-response question.
import { graph } from "../../plot.js";
import { scene, tank } from "../../diagrams.js";

const r = String.raw;
const one = (blocks, title = "") => [{ title, blocks }];
const pics = (word, svgs) => svgs.map((s, i) => ({ title: `${word} ${"ABCD"[i]}`, blocks: [{ svg: s }] }));
// numbers with units after the math: n("4.0", "m/s") gives "$4.0$ m/s"; sci("7.4", -4, "m³") gives "$7.4\times10^{-4}$ m³"
const n = (x, unit = "") => `$${x}$` + (unit ? " " + unit : "");
const sci = (a, e, unit = "") => "$" + a + r`\times10^{` + e + "}$" + (unit ? " " + unit : "");

// ---- graphs and diagrams ----
// 8.1: mass versus volume for two liquids
const massVol = graph({ x: [0, 60], y: [0, 100], step: { x: 10, y: 20 }, xname: "V (cm³)", yname: "m (g)", segments: [[0, 0, 50, 100], [0, 0, 50, 40]], dots: [[50, 100, "closed"], [50, 40, "closed"]], labels: [[52, 100, "X"], [52, 40, "Y"]],
  alt: "Mass in grams versus volume in cubic centimeters for two liquids. Both graphs are straight lines through the origin. The line for liquid X passes through 50 cubic centimeters and 100 grams. The line for liquid Y passes through 50 cubic centimeters and 40 grams." });

// 8.2: absolute pressure versus depth in an open tank and a sealed tank (the same liquid, density 800 kg/m³, g = 10 m/s²)
const pDepth = graph({ x: [0, 6], y: [0, 240], step: { x: 1, y: 20 }, labelEvery: 1, xname: "h (m)", yname: "P (kPa)", segments: [[0, 100, 5, 140], [0, 160, 5, 200]], dots: [[0, 100, "closed"], [5, 140, "closed"], [0, 160, "closed"], [5, 200, "closed"]], labels: [[5.15, 140, "Tank 1"], [5.15, 200, "Tank 2"]],
  alt: "Absolute pressure in kilopascals versus depth in meters for two tanks. The line for tank 1 is straight, starting at 100 kilopascals at 0 meters and reaching 140 kilopascals at 5 meters. The line for tank 2 is parallel, starting at 160 kilopascals at 0 meters and reaching 200 kilopascals at 5 meters." });

// 8.2: a U-tube with water and oil
const uTube = scene({ width: 300, height: 270, alt: "A U-shaped tube open at both ends. The left arm holds water. The right arm holds water at the bottom and a column of oil 20 centimeters tall above the boundary between oil and water. The water surface in the left arm is a height h above the level of the boundary. A dashed horizontal line marks the level of the boundary.", items: [
  { poly: { points: [[70, 40], [190, 40], [190, 100], [154, 100], [154, 70], [106, 70], [106, 180], [70, 180]], fill: "fluid" } },
  { poly: { points: [[154, 100], [190, 100], [190, 200], [154, 200]], fill: "body" } },
  { rope: { points: [[70, 245], [70, 40], [190, 40], [190, 245]], cls: "d-wall" } },
  { rope: { points: [[106, 245], [106, 70], [154, 70], [154, 245]], cls: "d-wall" } },
  { line: { from: [20, 100], to: [235, 100], dash: true } }, { line: { from: [20, 180], to: [70, 180], dash: true } }, { line: { from: [190, 200], to: [235, 200], dash: true } },
  { arrow: { from: [38, 140], to: [38, 180], kind: "plain" } }, { arrow: { from: [38, 140], to: [38, 100], kind: "plain" } }, { label: { x: 26, y: 140, text: "h", anchor: "end" } },
  { arrow: { from: [222, 150], to: [222, 200], kind: "plain" } }, { arrow: { from: [222, 150], to: [222, 100], kind: "plain" } }, { label: { x: 232, y: 150, text: "20 cm", anchor: "start" } },
  { label: { x: 172, y: 150, text: "oil" } }, { label: { x: 130, y: 55, text: "water" } },
] });

// 8.2: a tank with a point P at depth h
const tankP = tank({ level: 190, depth: 80, labels: { depth: "h", point: "P" }, alt: "A tank of water. A point P is marked below the surface at a depth h." });
// 8.3: a floating block with the buoyant force and the weight
const tankBlock = tank({ level: 190, block: { kind: "floating", label: "m", forces: true }, alt: "A block of mass m floats at rest in a liquid with part of the block above the surface. An upward arrow labeled F_B and a downward arrow labeled mg, of equal length, act on the block." });
// 8.3: a block hanging from a string, lowered into a beaker of water
const tankHang = tank({ level: 190, block: { kind: "submerged", label: "M" }, alt: "A block labeled M hangs from a string and is completely under the water in a beaker. The block does not touch the sides or the bottom." });

// 8.3: four free-body diagrams for a ball held under water
const ballFBD = (forces, alt) => {
  const cy = 120, rb = 16, k = 0.8, items = [{ circle: { x: 95, y: cy, r: rb } }];
  for (const f of forces) {
    const x = 95 + f.dx, s0 = cy + (f.up ? rb : -rb), y2 = s0 + (f.up ? 1 : -1) * f.len * k;
    items.push({ arrow: { from: [x, s0], to: [x, y2], kind: "force" } });
    if (f.dx) items.push({ label: { x: x + (f.dx < 0 ? -8 : 8), y: y2 + (f.up ? 2 : -2), text: f.label, anchor: f.dx < 0 ? "end" : "start" } });
    else items.push({ label: { x, y: y2 + (f.up ? 14 : -14), text: f.label } });
  }
  return scene({ width: 190, height: 245, alt, items });
};
const fbdPics = [
  ballFBD([{ up: true, len: 60, dx: -24, label: "F_B" }, { up: false, len: 100, dx: 0, label: "mg" }, { up: true, len: 40, dx: 24, label: "F_rod" }], "Free-body diagram A. An upward arrow F_B of length 60, a longer downward arrow mg of length 100, and an upward arrow F_rod of length 40."),
  ballFBD([{ up: true, len: 60, dx: 0, label: "F_B" }, { up: false, len: 60, dx: -24, label: "mg" }, { up: false, len: 40, dx: 24, label: "F_rod" }], "Free-body diagram B. An upward arrow F_B of length 60, a downward arrow mg of length 60, and a downward arrow F_rod of length 40."),
  ballFBD([{ up: true, len: 100, dx: 0, label: "F_B" }, { up: false, len: 60, dx: -24, label: "mg" }, { up: false, len: 40, dx: 24, label: "F_rod" }], "Free-body diagram C. An upward arrow F_B of length 100, a downward arrow mg of length 60, and a downward arrow F_rod of length 40."),
  ballFBD([{ up: true, len: 100, dx: -12, label: "F_B" }, { up: false, len: 60, dx: 12, label: "mg" }], "Free-body diagram D. An upward arrow F_B of length 100 and a downward arrow mg of length 60."),
];

// 8.3: tension in a string as a cube is lowered into water (cube of edge 0.10 m, mass 2.0 kg, g = 10 m/s²)
const tensionGraph = graph({ x: [0, 0.2], y: [0, 25], step: { x: 0.05, y: 5 }, xname: "d (m)", yname: "T (N)", segments: [[0, 20, 0.1, 10], [0.1, 10, 0.2, 10]], dots: [[0, 20, "closed"], [0.1, 10, "closed"], [0.2, 10, "closed"]],
  alt: "String tension in newtons versus depth of the cube's bottom face in meters. The tension falls in a straight line from 20 newtons at 0 meters to 10 newtons at 0.10 meters, then stays at 10 newtons out to 0.20 meters." });

// 8.4 and QQT: pipes
const pipeDiagram = tank({ pipe: true, labels: { v1: "v_1", v2: "v_2", a1: "A_1", a2: "A_2" }, alt: "A horizontal pipe that is wide on the left and narrow on the right. Water flows to the right. The speed v_1 and the cross-sectional area A_1 are marked in the wide section, and the speed v_2 and the area A_2 in the narrow section." });
const venturi = scene({ width: 480, height: 250, alt: "A horizontal pipe, wide on the left with cross-sectional area A_1 and narrow on the right with area A_2. Water flows to the right with speed v_1 in the wide section and v_2 in the narrow section. An open vertical tube rises from each section. The water stands higher in the tube over the wide section than in the tube over the narrow section, and the difference in the two water levels is marked Δh.", items: [
  { poly: { points: [[30, 130], [150, 130], [215, 110], [410, 110], [410, 70], [215, 70], [150, 50], [30, 50]], fill: "fluid" } },
  { fluid: { x: 82, y: 130, w: 16, h: 75 } }, { fluid: { x: 312, y: 110, w: 16, h: 55 } },
  { rope: { points: [[30, 130], [82, 130]], cls: "d-wall" } }, { rope: { points: [[98, 130], [150, 130], [215, 110], [312, 110]], cls: "d-wall" } }, { rope: { points: [[328, 110], [410, 110]], cls: "d-wall" } },
  { rope: { points: [[30, 50], [150, 50], [215, 70], [410, 70]], cls: "d-wall" } },
  { rope: { points: [[82, 130], [82, 232]], cls: "d-wall" } }, { rope: { points: [[98, 130], [98, 232]], cls: "d-wall" } },
  { rope: { points: [[312, 110], [312, 232]], cls: "d-wall" } }, { rope: { points: [[328, 110], [328, 232]], cls: "d-wall" } },
  { arrow: { from: [38, 90], to: [74, 90], kind: "velocity" } }, { label: { x: 56, y: 102, text: "v_1" } },
  { arrow: { from: [235, 90], to: [295, 90], kind: "velocity" } }, { label: { x: 265, y: 100, text: "v_2" } },
  { line: { from: [125, 50], to: [125, 130], dash: true } }, { label: { x: 125, y: 34, text: "A_1" } },
  { line: { from: [370, 70], to: [370, 110], dash: true } }, { label: { x: 370, y: 54, text: "A_2" } },
  { line: { from: [98, 205], to: [455, 205], dash: true } }, { line: { from: [328, 165], to: [455, 165], dash: true } },
  { arrow: { from: [440, 185], to: [440, 205], kind: "plain" } }, { arrow: { from: [440, 185], to: [440, 165], kind: "plain" } }, { label: { x: 450, y: 185, text: "Δh", anchor: "start" } },
] });

// ---- sets ----
export const sets = {
  "p8r-s01": { name: "Four solid samples", label: "Table", intro: r`A student measures the mass and the volume of four solid samples. The results are shown in the table.`,
    sources: one([{ table: { head: ["Sample", "Mass (g)", "Volume (cm³)"], rows: [["A", "$81$", "$30$"], ["B", "$108$", "$30$"], ["C", "$54$", "$20$"], ["D", "$54$", "$10$"]] } }]) },
  "p8r-s02": { name: "Mass and volume of two liquids", label: "Graph", intro: r`The graph shows the mass $m$ of a sample of liquid X and of a sample of liquid Y as a function of the volume $V$ of the sample.`, sources: one([{ svg: massVol }]) },
  "p8r-s03": { name: "Pressure in two tanks", label: "Graph", intro: r`The same liquid is in two tanks. Tank 1 is open to the atmosphere. Tank 2 is sealed, with a gas above the liquid. The graph shows the absolute pressure $P$ at a depth $h$ below the liquid surface in each tank.`, sources: one([{ svg: pDepth }]) },
  "p8r-s04": { name: "Oil and water in a U-tube", label: "Diagram", intro: r`A U-shaped tube that is open at both ends contains water. Oil with a density of $800$ kg/m³ is poured into the right arm. At equilibrium, the column of oil is $20$ cm tall above the boundary between the oil and the water. The water surface in the left arm is a height $h$ above the level of that boundary, as shown.`, sources: one([{ svg: uTube }]) },
  "p8r-s05": { name: "A point in a tank", label: "Diagram", intro: r`A tank is filled with water to the level shown. Point $P$ is at a depth $h$ below the water surface.`, sources: one([{ svg: tankP }]) },
  "p8r-s06": { name: "A floating block", label: "Diagram", intro: r`A solid block of mass $m$ and density $\rho_b$ floats at rest in a liquid of density $\rho_f$, where $\rho_b < \rho_f$. The buoyant force $F_B$ and the weight $mg$ on the block are shown.`, sources: one([{ svg: tankBlock }]) },
  "p8r-s07": { name: "A ball held under water", label: "Diagrams", intro: r`A ball made of a material that is less dense than water is held completely under water, at rest, by a thin rod that pushes straight down on the ball from above. Four free-body diagrams are shown. $F_B$ is the buoyant force, $mg$ is the weight, and $F_{rod}$ is the force exerted by the rod. The arrow lengths show the relative magnitudes of the forces.`, sources: pics("Diagram", fbdPics) },
  "p8r-s08": { name: "A cube lowered into water", label: "Graph", intro: r`A cube hangs from a string and is lowered slowly into a tank of water ($1000$ kg/m³) with its bottom face horizontal, until the cube is completely submerged. The graph shows the tension $T$ in the string as a function of the depth $d$ of the cube's bottom face below the water surface. Use $g = 10$ m/s².`, sources: one([{ svg: tensionGraph }]) },
  "p8r-s09": { name: "A block lowered into a beaker", label: "Diagram", intro: r`A beaker holds water, and the beaker and water together have a mass of $2.00$ kg. The beaker sits on a scale that reads in kilograms. A block of mass $0.50$ kg and volume $2.0 \times 10^{-4}$ m³ hangs from a string held by a stand. The block is lowered until it is completely under the water, and it does not touch the beaker. No water spills.`, sources: one([{ svg: tankHang }]) },
  "p8r-s10": { name: "Water in a pipe that narrows", label: "Diagram", intro: r`Water, which can be treated as an ideal fluid with a density of $1000$ kg/m³, flows steadily through a horizontal pipe that narrows, as shown. The wide section has an area $A_1 = 4.0A_2$, and the water in it moves at $v_1 = 1.0$ m/s. The figure is not drawn to scale.`, sources: one([{ svg: pipeDiagram }]) },
  "p8r-s11": { name: "A floating tube and a hose nozzle", label: "Free response", frq: "EDA",
    intro: r`A student does two experiments with fluids.`,
    sources: [{ title: "Experiment 1", blocks: [{ p: r`A uniform, sealed test tube of mass $M$ and circular cross-sectional area $A$ floats upright in a tall container of a liquid of unknown density $\rho$. The student can place small identical washers inside the tube. When the tube floats at rest, a length $d$ of the tube is below the liquid surface. The student has a balance, a meter stick, calipers, a stopwatch, and a supply of washers.` }] },
      { title: "Experiment 2", blocks: [{ p: r`A hose supplies water at a constant volume flow rate $Q$. The student fits circular nozzles of different inner diameters $d$ to the end of the hose, and measures the speed $v$ of the water as it leaves each nozzle with a speed sensor. The data are shown in the table. The student wants to determine $Q$.` },
        { table: { head: ["Trial", "Nozzle diameter $d$ (cm)", "Exit speed $v$ (m/s)"], rows: [["1", "$1.0$", "$3.8$"], ["2", "$1.2$", "$2.7$"], ["3", "$1.5$", "$1.7$"], ["4", "$2.0$", "$0.95$"], ["5", "$2.5$", "$0.61$"]] } }] }] },
  "p8r-s12": { name: "Water in a pipe with two open tubes", label: "Free response", frq: "QQT",
    intro: r`Water of density $\rho$ flows steadily from left to right through a horizontal pipe that narrows, as shown. The cross-sectional area is $A_1$ in the wide section and $A_2$ in the narrow section, and the speed of the water in the wide section is $v_1$. An open vertical tube is attached to each section. The water stands higher in the tube over the wide section than in the tube over the narrow section, and the difference between the two water levels is $\Delta h$. Treat the water as an ideal fluid. Express algebraic answers in terms of $\rho$, $v_1$, $A_1$, $A_2$, and $g$.`,
    sources: one([{ svg: venturi }]) },
};

// ---- multiple choice ----
const mc = (id, topic, difficulty, o) => ({ id: `p8r-${id}`, type: "mcq", skill: "u8", topic, difficulty, ...o, answer: 0 });
const S = (k) => `p8r-s${String(k).padStart(2, "0")}`;

const mcq = [
  // 8.1 Internal structure and density
  mc("m01", "8.1", "easy", { stem: "A solid block of aluminum is cut into two pieces. One piece has three times the volume of the other piece.", question: "How do the densities of the two pieces compare?",
    choices: ["They are equal.", "The larger piece has three times the density of the smaller piece.", "The smaller piece has three times the density of the larger piece.", "The larger piece has the greater density, but it is less than three times as great."],
    why: [r`Density is $\rho = m/V$ and depends on the material. A piece with three times the volume also has three times the mass, so the ratio $m/V$ is the same for both pieces.`, r`The larger piece has three times the mass, but it also has three times the volume. The factors cancel in $m/V$.`, r`The smaller piece has one third of the mass and one third of the volume, so its density is unchanged.`, r`The two pieces are the same material, so their densities are exactly equal, not nearly equal.`] }),
  mc("m02", "8.1", "easy", { set: S(1), question: "Which two samples could be made of the same material?",
    choices: ["A and C", "A and B", "C and D", "B and D"],
    why: [r`The densities are A: $81/30 = 2.7$, B: $108/30 = 3.6$, C: $54/20 = 2.7$, and D: $54/10 = 5.4$ g/cm³. Samples A and C have equal densities.`, r`A and B have the same volume, but their masses differ, so their densities are $2.7$ and $3.6$ g/cm³.`, r`C and D have the same mass, but their volumes differ, so their densities are $2.7$ and $5.4$ g/cm³.`, r`B and D have the two highest densities, but those densities are $3.6$ and $5.4$ g/cm³, which are not equal.`] }),
  mc("m03", "8.1", "moderate", { set: S(1), question: "What is the volume of $2.0$ kg of the material that sample C is made of?",
    choices: [sci("7.4", -4, "m³"), sci("5.4", 3, "m³"), sci("7.4", -1, "m³"), sci("7.4", -7, "m³")],
    why: [r`The density of C is $54\text{ g}/20\text{ cm}^3 = 2.7$ g/cm³ $= 2.7 \times 10^{3}$ kg/m³. Then $V = m/\rho = 2.0/(2.7 \times 10^{3}) = 7.4 \times 10^{-4}$ m³.`, r`This multiplies the mass by the density, $(2.0)(2.7 \times 10^{3})$, instead of dividing.`, r`This divides by $2.7$, the density in g/cm³, but the mass is in kilograms, so the density must be in kg/m³.`, r`This converts the density with a factor of $10^{6}$ instead of $10^{3}$, as if converting cm³ to m³ for a mass in grams.`] }),
  mc("m04", "8.1", "moderate", { set: S(2), stem: "A student mixes $40$ g of liquid X with $40$ g of liquid Y. Assume that the volume of the mixture is the sum of the volumes of the two liquids.", question: "What is the density of the mixture?",
    choices: [sci("1.1", 3, "kg/m³"), sci("1.4", 3, "kg/m³"), sci("1.6", 3, "kg/m³"), sci("2.8", 3, "kg/m³")],
    why: [r`The slopes are $\rho_X = 100/50 = 2.0$ g/cm³ and $\rho_Y = 40/50 = 0.80$ g/cm³. The volumes are $V_X = 40/2.0 = 20$ cm³ and $V_Y = 40/0.80 = 50$ cm³. The mixture has $80\text{ g}/70\text{ cm}^3 = 1.14$ g/cm³ $\approx 1.1 \times 10^{3}$ kg/m³.`, r`This averages the two densities, $(2.0 + 0.80)/2$. That works only for equal volumes. Here the masses are equal, and liquid Y takes up more volume.`, r`This divides the total mass, $80$ g, by the volume of liquid Y alone, $50$ cm³.`, r`This adds the two densities, $2.0 + 0.80$. Densities do not add.`] }),
  mc("m05", "8.1", "moderate", { stem: r`A solid object has a weight of $49$ N on Earth and a volume of $2.0$ L. Use $g = 9.8$ m/s² and $1\text{ L} = 10^{-3}\text{ m}^3$.`, question: "What is the density of the object?",
    choices: [sci("2.5", 3, "kg/m³"), sci("2.5", 4, "kg/m³"), sci("2.4", 5, "kg/m³"), sci("2.5", 0, "kg/m³")],
    why: [r`The mass is $W/g = 49/9.8 = 5.0$ kg and the volume is $2.0 \times 10^{-3}$ m³. Then $\rho = m/V = 5.0/(2.0 \times 10^{-3}) = 2.5 \times 10^{3}$ kg/m³.`, r`This divides the weight, $49$ N, by the volume. Density needs the mass, not the weight.`, r`This multiplies the weight by $g$ again, $(49)(9.8)/(2.0 \times 10^{-3})$, instead of dividing by $g$.`, r`This uses the volume as $2.0$ m³ instead of converting liters to cubic meters.`] }),
  mc("m06", "8.1", "easy", { stem: r`A solid sphere of radius $R$ has a mass $M$. A second solid sphere is made of the same material and has a radius $2R$.`, question: "What is the mass of the second sphere?",
    choices: [r`$8M$`, r`$2M$`, r`$4M$`, r`$6M$`],
    why: [r`The mass is $\rho V$ and $V = \tfrac{4}{3}\pi R^3$, so the mass is proportional to $R^3$. Doubling $R$ multiplies the mass by $2^3 = 8$.`, r`This scales the mass with $R$. The volume, and so the mass, depends on $R^3$.`, r`This scales the mass with $R^2$, the way surface area scales.`, r`This multiplies the factor $2$ by the exponent $3$ instead of raising $2$ to the third power.`] }),

  // 8.2 Pressure
  mc("m07", "8.2", "easy", { set: S(3), question: "What is the absolute pressure of the gas above the liquid in tank 2?",
    choices: [n(160, "kPa"), n(60, "kPa"), n(100, "kPa"), n(200, "kPa")],
    why: [r`The gas rests on the liquid surface, which is at depth $h = 0$. The line for tank 2 is at $160$ kPa there.`, r`This is the difference between the two lines, $160 - 100$. It is the extra pressure over the atmosphere (a gauge pressure), not the absolute pressure of the gas.`, r`This is the pressure at the surface of tank 1, which is open to the atmosphere.`, r`This is the pressure in tank 2 at a depth of $5$ m, not at the surface.`] }),
  mc("m08", "8.2", "difficult", { set: S(3), stem: r`Use $g = 10$ m/s².`, question: "What is the density of the liquid?",
    choices: [sci("8.0", 2, "kg/m³"), sci("2.8", 3, "kg/m³"), sci("4.0", 3, "kg/m³"), sci("8.0", 3, "kg/m³")],
    why: [r`The pressure changes with depth by $\Delta P = \rho g\,\Delta h$. For tank 1, $\Delta P = 40$ kPa over $\Delta h = 5$ m. Then $\rho = \dfrac{\Delta P}{g\,\Delta h} = \dfrac{4.0 \times 10^{4}}{(10)(5)} = 8.0 \times 10^{2}$ kg/m³.`, r`This divides the absolute pressure at $5$ m, $140$ kPa, by $gh$. The density depends on the change in pressure, not on the absolute pressure, which includes the atmosphere.`, r`This divides the change in pressure by $g$ and leaves out the depth, $(4.0 \times 10^{4})/10$.`, r`This is the slope in Pa per meter, $8.0 \times 10^{3}$. The slope equals $\rho g$, so it must be divided by $g$.`] }),
  mc("m09", "8.2", "moderate", { set: S(4), question: r`What is the height $h$?`,
    choices: [n(16, "cm"), n(20, "cm"), n(25, "cm"), n(13, "cm")],
    why: [r`The pressures on the two sides are equal at the level of the boundary. On the right, $P = P_0 + \rho_{oil}\,g\,(0.20\text{ m})$. On the left, $P = P_0 + \rho_w\,g\,h$. Then $h = (800/1000)(20) = 16$ cm.`, r`This assumes the water column in the left arm is as tall as the oil column. The oil is less dense, so the water column that balances it is shorter.`, r`This uses the ratio of the densities upside down, $(1000/800)(20)$.`, r`This multiplies by the density ratio twice, $(0.80)^2(20) = 12.8$ cm.`] }),
  mc("m10", "8.2", "easy", { set: S(5), stem: "The water is poured out, and the tank is refilled to the same level with a liquid that has twice the density of water.", question: "How does the gauge pressure at point $P$ compare with its value in the water?",
    choices: ["Twice as great", "Equal to its value in water", "One half as great", "Four times as great"],
    why: [r`The gauge pressure is $\rho g h$. With the same $h$ and twice the density, the gauge pressure is twice as great.`, r`The pressure at a given depth depends on the density of the fluid, so a denser liquid gives a greater pressure at the same depth.`, r`This divides by the density ratio instead of multiplying.`, r`This squares the density ratio. The pressure is proportional to $\rho$, not $\rho^2$.`] }),
  mc("m11", "8.2", "moderate", { stem: r`A circular hatch of radius $0.20$ m on a research submersible is $30$ m below the surface of a lake of water ($1000$ kg/m³). The air inside the submersible is at atmospheric pressure, $1.0 \times 10^{5}$ Pa. Use $g = 9.8$ m/s².`, question: "What is the magnitude of the net force on the hatch due to the pressure difference between the two sides?",
    choices: [sci("3.7", 4, "N"), sci("5.0", 4, "N"), sci("1.5", 5, "N"), sci("1.2", 4, "N")],
    why: [r`The air inside balances the atmosphere above the lake, so the net pressure difference is the gauge pressure, $\rho g h = (1000)(9.8)(30) = 2.94 \times 10^{5}$ Pa. The area is $\pi r^2 = \pi(0.20)^2 = 0.126$ m². Then $F = PA = 3.7 \times 10^{4}$ N.`, r`This uses the absolute pressure at $30$ m, $3.94 \times 10^{5}$ Pa. The air inside pushes outward with $1.0 \times 10^{5}$ Pa, so only the gauge pressure gives the net force.`, r`This uses the diameter in place of the radius, $\pi(0.40)^2$, which makes the area four times too large.`, r`This uses $r^2 = 0.040$ m² for the area and leaves out the factor of $\pi$.`] }),
  mc("m12", "8.2", "moderate", { stem: r`A diver is at a depth of $10$ m in a lake. The diver then descends to a depth of $30$ m. Use $P_{atm} = 1.0 \times 10^{5}$ Pa, $\rho = 1000$ kg/m³, and $g = 9.8$ m/s².`, question: "How does the absolute pressure at $30$ m compare with the absolute pressure at $10$ m?",
    choices: ["About twice as great", "Exactly three times as great", "About 1.5 times as great", "About four times as great"],
    why: [r`At $10$ m, $P = 1.0 \times 10^{5} + (1000)(9.8)(10) = 1.98 \times 10^{5}$ Pa. At $30$ m, $P = 1.0 \times 10^{5} + (1000)(9.8)(30) = 3.94 \times 10^{5}$ Pa. The ratio is $1.99$.`, r`Only the gauge pressure triples, because it is proportional to depth. The absolute pressure includes the constant $P_{atm}$.`, r`This compares the gauge pressure at $30$ m, $2.94 \times 10^{5}$ Pa, with the absolute pressure at $10$ m, $1.98 \times 10^{5}$ Pa.`, r`This compares the absolute pressure at $30$ m with the gauge pressure at $10$ m, $3.94/0.98$.`] }),

  // 8.3 Fluids and Newton's laws
  mc("m13", "8.3", "easy", { set: S(6), question: r`How does the magnitude of the buoyant force $F_B$ compare with the weight $mg$?`,
    choices: [r`Equal to $mg$`, r`Greater than $mg$`, r`Less than $mg$`, r`Equal to $2mg$`],
    why: [r`The block is at rest, so the net force on it is zero. The upward buoyant force and the downward weight must have equal magnitudes.`, r`If $F_B$ were greater than $mg$, the block would accelerate upward.`, r`If $F_B$ were less than $mg$, the block would sink.`, r`If $F_B$ were $2mg$, the net force would be $mg$ upward, and the block would accelerate upward.`] }),
  mc("m14", "8.3", "moderate", { set: S(6), question: "What fraction of the volume of the block is below the liquid surface?",
    choices: [r`$\dfrac{\rho_b}{\rho_f}$`, r`$\dfrac{\rho_f}{\rho_b}$`, r`$1 - \dfrac{\rho_b}{\rho_f}$`, r`$\dfrac{\rho_b}{\rho_b + \rho_f}$`],
    why: [r`The buoyant force equals the weight: $\rho_f V_{sub}\,g = \rho_b V g$. Then $V_{sub}/V = \rho_b/\rho_f$.`, r`This is the inverse. It is greater than $1$, which is impossible for a block that floats.`, r`This is the fraction of the volume that is above the surface.`, r`This does not follow from the force balance. When $\rho_b = \rho_f$ it gives $\tfrac12$, but the block would be completely submerged.`] }),
  mc("m15", "8.3", "difficult", { set: S(6), stem: r`A small object of mass $M$ is placed on top of the block. The block now floats at rest with its top surface exactly level with the liquid surface, and the object stays dry.`, question: r`What is $M$ in terms of $m$, $\rho_b$, and $\rho_f$?`,
    choices: [r`$m\left(\dfrac{\rho_f}{\rho_b} - 1\right)$`, r`$m\left(\rho_f - \rho_b\right)$`, r`$m\,\dfrac{\rho_f}{\rho_b}$`, r`$m\left(1 - \dfrac{\rho_b}{\rho_f}\right)$`],
    why: [r`The block's volume is $V = m/\rho_b$ and it is fully submerged, so $F_B = \rho_f V g = \rho_f (m/\rho_b) g$. This equals the total weight, $(m + M)g$. Then $M = m\,\rho_f/\rho_b - m = m\left(\dfrac{\rho_f}{\rho_b} - 1\right)$.`, r`This is not dimensionally a mass. It multiplies $m$ by a difference of densities instead of a ratio.`, r`This is the total mass $m + M$, not the added mass $M$. The block's own mass must be subtracted.`, r`This multiplies $m$ by the fraction of the block that was above the surface. The needed mass depends on $\rho_f/\rho_b$, not on this fraction of $m$.`] }),
  mc("m16", "8.3", "moderate", { set: S(7), question: "Which diagram shows the forces on the ball?",
    choices: ["Diagram C", "Diagram A", "Diagram B", "Diagram D"],
    why: [r`The ball is at rest, so the forces balance. The weight and the rod's force, both down, together equal the buoyant force, up: $F_B = mg + F_{rod}$. Diagram C shows $100 = 60 + 40$.`, r`The rod pushes down, not up. This diagram balances only because the rod's force is drawn in the wrong direction.`, r`The buoyant force is not equal to the weight here. With the rod pushing down, the downward forces total $100$ and the upward force is only $60$, so the ball would accelerate downward.`, r`The rod's force is missing. Without it, the buoyant force is greater than the weight and the ball would accelerate upward.`] }),
  mc("m17", "8.3", "moderate", { set: S(8), question: "What is the density of the cube?",
    choices: [sci("2.0", 3, "kg/m³"), sci("1.0", 3, "kg/m³"), sci("5.0", 2, "kg/m³"), sci("3.0", 3, "kg/m³")],
    why: [r`The tension at $d = 0$ is the weight, $W = 20$ N, so $m = 2.0$ kg. When the cube is fully submerged, $T = W - F_B$, so $F_B = 10$ N and $V = F_B/(\rho_w g) = 10/(1000 \cdot 10) = 1.0 \times 10^{-3}$ m³. Then $\rho = 2.0/1.0 \times 10^{-3} = 2.0 \times 10^{3}$ kg/m³.`, r`This takes the final tension, $10$ N, as the weight. The tension at $d = 0$ is the weight, $20$ N.`, r`This inverts the ratio of forces, $\rho = \rho_w F_B/W$. The cube is denser than water because its weight is greater than the buoyant force.`, r`This finds the weight as the sum of the two readings, $20 + 10$, instead of using the reading at $d = 0$.`] }),
  mc("m18", "8.3", "moderate", { set: S(8), question: r`What is the tension in the string when $d = 0.050$ m?`,
    choices: [n(15, "N"), n(10, "N"), n(5.0, "N"), n(25, "N")],
    why: [r`The cube's edge is $0.10$ m (the tension stops changing there), so at $d = 0.050$ m half of the cube is submerged. The buoyant force is half of its full value, $5.0$ N, and $T = 20 - 5.0 = 15$ N.`, r`This is the tension when the cube is completely submerged, which happens at $d = 0.10$ m.`, r`This is the buoyant force, not the tension. The tension is the weight minus the buoyant force.`, r`This adds the buoyant force to the weight instead of subtracting it.`] }),
  mc("m19", "8.3", "difficult", { set: S(9), question: "What does the scale read?",
    choices: [n("2.20", "kg"), n("2.00", "kg"), n("2.30", "kg"), n("2.50", "kg")],
    why: [r`The block exerts a downward force on the water equal to the buoyant force on the block (Newton's third law), $F_B = \rho_w V g = (1000)(2.0 \times 10^{-4})(9.8) = 1.96$ N. This equals the weight of $0.20$ kg. The scale reads $2.00 + 0.20 = 2.20$ kg.`, r`The block is supported by the string, but the water still pushes up on the block, so the block pushes down on the water. The scale reading increases.`, r`This adds the block's apparent weight, $0.50 - 0.20 = 0.30$ kg. The scale supports the buoyant force, not the apparent weight.`, r`This adds the full weight of the block, which would be correct only if the block rested on the bottom of the beaker.`] }),
  mc("m20", "8.3", "moderate", { stem: r`Three blocks, A, B, and C, each have a volume of $1.0 \times 10^{-3}$ m³ and masses of $0.40$ kg, $0.90$ kg, and $1.5$ kg. Each block is placed in a tank of water ($1000$ kg/m³) and comes to rest.`, question: "Which ranking of the magnitudes of the buoyant forces on the blocks, from greatest to least, is correct?",
    choices: ["C > B > A", "A = B = C", "A > B > C", "B = C > A"],
    why: [r`Blocks A and B float, so $F_B = mg$: $3.9$ N and $8.8$ N. Block C is denser than water ($1500$ kg/m³), so it rests on the bottom, completely submerged, and $F_B = \rho_w V g = 9.8$ N. The ranking is C, B, A.`, r`The blocks have equal volumes, but the buoyant force depends on the volume of water displaced. Blocks A and B float and displace less water than their full volume.`, r`This ranks by how high each block floats, as if the lighter block displaced more. A floating block displaces its own weight of water, so the lighter block displaces less.`, r`Block B floats with only part of its volume submerged, so its buoyant force, $8.8$ N, is less than the $9.8$ N on the fully submerged block C.`] }),
  mc("m21", "8.3", "moderate", { stem: r`A block of mass $1.5$ kg and volume $1.0 \times 10^{-3}$ m³ is released from rest just below the surface of a tank of water ($1000$ kg/m³). Use $g = 9.8$ m/s².`, question: "What is the initial acceleration of the block?",
    choices: [n(3.3, "m/s² downward"), n(4.9, "m/s² downward"), n(6.5, "m/s² upward"), n(9.8, "m/s² downward")],
    why: [r`The weight is $(1.5)(9.8) = 14.7$ N and the buoyant force is $(1000)(1.0 \times 10^{-3})(9.8) = 9.8$ N. The net force is $4.9$ N downward, so $a = 4.9/1.5 = 3.3$ m/s² downward.`, r`This is the net force in newtons. It must be divided by the mass.`, r`This divides only the buoyant force by the mass, $9.8/1.5$, as if the weight were not acting.`, r`This is free-fall acceleration. The buoyant force reduces the net force on the block.`] }),
  mc("m22", "8.3", "difficult", { stem: "A beaker holds water and a floating cube of ice. A small steel ball is frozen inside the ice cube. The ice melts completely, and the steel ball sinks to the bottom of the beaker.", question: "What happens to the water level in the beaker?",
    choices: ["It falls, because the ball displaces less water on the bottom than it did while held up by the ice.", "It stays the same, because the floating ice displaces its own weight of water and melts into that much water.", "It rises, because the melted ice adds water to the beaker and the ball takes up space on the bottom.", "It rises, because the ball pushes water upward as it sinks to the bottom of the beaker."],
    why: [r`With the ice, the water displaced has a volume $(m_{ice} + m_{ball})/\rho_w$. After melting, the volume is the ice's meltwater, $m_{ice}/\rho_w$, plus the ball's own volume, $m_{ball}/\rho_{steel}$. Steel is denser than water, so $m_{ball}/\rho_{steel} < m_{ball}/\rho_w$ and the level falls.`, r`This would be correct for ice alone. The ball also floated while it was in the ice, displacing its weight of water, and now it displaces much less.`, r`The meltwater only replaces the volume of water that the ice displaced. The steel ball displaces less water on the bottom than it did in the ice, so the level still falls.`, r`The ball does not raise the level when it sinks. It displaces less water on the bottom than it did while held up by the ice.`] }),
  mc("m23", "8.3", "difficult", { stem: r`An object hangs from a spring scale. The scale reads $10.0$ N with the object in air, $6.0$ N with the object completely submerged in water ($1000$ kg/m³), and $6.6$ N with the object completely submerged in an oil.`, question: "What is the density of the oil?",
    choices: [sci("8.5", 2, "kg/m³"), sci("1.1", 3, "kg/m³"), sci("1.2", 3, "kg/m³"), sci("6.6", 2, "kg/m³")],
    why: [r`The buoyant forces are $F_w = 10.0 - 6.0 = 4.0$ N in water and $F_o = 10.0 - 6.6 = 3.4$ N in oil. The object's volume is the same in both, so $F_o/F_w = \rho_o/\rho_w$ and $\rho_o = (3.4/4.0)(1000) = 850$ kg/m³.`, r`This compares the scale readings, $(6.6/6.0)(1000)$, instead of the buoyant forces. The readings are apparent weights.`, r`This inverts the ratio of the buoyant forces, $(4.0/3.4)(1000)$. The oil gives the smaller buoyant force, so it is less dense than water.`, r`This compares the reading in oil with the reading in air, $(6.6/10.0)(1000)$, which is not a ratio of buoyant forces.`] }),
  mc("m24", "8.3", "moderate", { stem: r`A scuba diver wearing gear has a total mass of $85$ kg and a total volume of $0.0900$ m³. The diver is completely under seawater of density $1025$ kg/m³ and is not swimming. Use $g = 9.8$ m/s².`, question: "What is the initial acceleration of the diver, if the diver is released from rest?",
    choices: [n(0.84, "m/s² upward"), n(0.84, "m/s² downward"), n(11, "m/s² upward"), n(0.77, "m/s² upward")],
    why: [r`The buoyant force is $(1025)(0.0900)(9.8) = 904$ N and the weight is $(85)(9.8) = 833$ N. The net force is $71$ N upward, and $a = 71/85 = 0.84$ m/s² upward.`, r`The buoyant force is greater than the weight, so the net force is upward.`, r`This divides only the buoyant force by the mass, $904/85$, and leaves out the weight.`, r`This divides the net force by the mass of the displaced seawater, $(71)/(92.3)$, instead of by the diver's mass.`] }),
  mc("m25", "8.3", "moderate", { stem: "A boat floats in a freshwater lake. The boat is then towed into the ocean, where the water is denser than fresh water.", question: "How do the buoyant force on the boat and the volume of water it displaces in the ocean compare with their values in the lake?",
    choices: ["The same force, a smaller volume", "A greater force, the same volume", "The same force, the same volume", "A greater force, a smaller volume"],
    why: [r`The boat floats at rest in both places, so $F_B$ equals the boat's weight, which does not change. Since $F_B = \rho V_{disp}\,g$, a greater $\rho$ means a smaller displaced volume.`, r`The buoyant force equals the weight in both cases, so it does not change. The denser water needs a smaller displaced volume to provide it.`, r`The force is the same, but the displaced volume is not. The denser water supplies the same force with less volume.`, r`The buoyant force cannot be greater, because the boat is at rest in both cases with the same weight.`] }),
  mc("m26", "8.3", "moderate", { stem: r`A cube with edges of length $0.20$ m is held at rest completely under water ($1000$ kg/m³), with its top face horizontal and $0.50$ m below the water surface. Use $g = 9.8$ m/s².`, question: "What is the net force exerted on the cube by the water, found from the pressure on its faces?",
    choices: [n("78.4", "N upward"), n(274, "N upward"), n(470, "N upward"), n("78.4", "N downward")],
    why: [r`The gauge pressure is $4900$ Pa on the top face (depth $0.50$ m) and $6860$ Pa on the bottom face (depth $0.70$ m). With an area of $0.040$ m², the forces are $196$ N down and $274$ N up. The net force is $274 - 196 = 78.4$ N upward, which equals $\rho_w V g$.`, r`This is the force on the bottom face alone. The top face pushes down with $196$ N.`, r`This adds the forces on the top and bottom faces. They point in opposite directions, so they subtract.`, r`The pressure is greater on the bottom face, so the net force is upward.`] }),

  // 8.4 Fluids and conservation laws
  mc("m27", "8.4", "easy", { set: S(10), question: r`What is the speed $v_2$ of the water in the narrow section?`,
    choices: [n("4.0", "m/s"), n("2.0", "m/s"), n("0.25", "m/s"), n(16, "m/s")],
    why: [r`By continuity, $A_1 v_1 = A_2 v_2$, so $v_2 = v_1 A_1/A_2 = (1.0)(4.0) = 4.0$ m/s.`, r`This scales the speed by the ratio of the diameters, which is $2$ for areas in the ratio $4$. The speed depends on the area ratio.`, r`This inverts the ratio, $v_1 A_2/A_1$. The water moves faster in the narrow section.`, r`This squares the area ratio. The speed changes by the area ratio itself.`] }),
  mc("m28", "8.4", "moderate", { set: S(10), question: r`What is the pressure difference $P_1 - P_2$ between the wide and narrow sections?`,
    choices: [sci("7.5", 3, "Pa"), sci("1.5", 4, "Pa"), sci("4.5", 3, "Pa"), sci("8.0", 3, "Pa")],
    why: [r`The pipe is horizontal, so Bernoulli's equation gives $P_1 - P_2 = \tfrac12\rho(v_2^2 - v_1^2) = \tfrac12(1000)(4.0^2 - 1.0^2) = 7.5 \times 10^{3}$ Pa.`, r`This leaves out the factor of $\tfrac12$: $\rho(v_2^2 - v_1^2)$.`, r`This squares the difference of the speeds, $\tfrac12\rho(v_2 - v_1)^2$, instead of the difference of the squares.`, r`This uses only the kinetic term at the narrow section, $\tfrac12\rho v_2^2$, and ignores the kinetic term at the wide section.`] }),
  mc("m29", "8.4", "easy", { stem: r`Water leaves a pipe with a cross-sectional area of $6.0 \times 10^{-4}$ m² at a speed of $0.50$ m/s.`, question: "What is the volume flow rate of the water?",
    choices: [sci("3.0", -4, "m³/s"), sci("1.2", -3, "m³/s"), sci("8.3", 2, "m³/s"), sci("5.0", -1, "m³/s")],
    why: [r`The volume flow rate is $Av = (6.0 \times 10^{-4})(0.50) = 3.0 \times 10^{-4}$ m³/s.`, r`This divides the area by the speed, $A/v$.`, r`This divides the speed by the area, $v/A$.`, r`This is the speed. The flow rate is the area times the speed.`] }),
  mc("m30", "8.4", "easy", { question: "Which of the following has the same units as pressure?",
    choices: [r`$\rho g h$`, r`$\rho g / h$`, r`$\rho v / h$`, r`$\rho h / g$`],
    why: [r`The units of $\rho g h$ are $(\text{kg/m}^3)(\text{m/s}^2)(\text{m}) = \text{kg}/(\text{m}\cdot\text{s}^2) = \text{Pa}$.`, r`$\rho g/h$ has units kg/(m³·s²). The depth must multiply, not divide.`, r`$\rho v/h$ has units kg/(m³·s). Pressure needs a factor of $v^2$, as in $\tfrac12\rho v^2$.`, r`$\rho h/g$ has units kg·s²/m³. The factor $g$ must multiply, not divide.`] }),
  mc("m31", "8.4", "easy", { stem: "Blood flows from the aorta into the capillaries. Each capillary is much narrower than the aorta, but the total cross-sectional area of all the capillaries together is much larger than that of the aorta.", question: "How does the speed of the blood in the capillaries compare with its speed in the aorta?",
    choices: ["Slower, because the total area is larger", "Faster, because each capillary is narrower", "The same, because the flow rate is the same", "Faster, because the pressure there is lower"],
    why: [r`The total volume flow rate is the same in both, $A_{total}v$. The capillaries have a much larger total area, so the blood moves more slowly there.`, r`The continuity equation applies to the total area of all the vessels in parallel, not to the width of one capillary.`, r`The volume flow rate is the same, but the speed is the flow rate divided by the area, and the area is different.`, r`Lower pressure does not require a higher speed. The speed is set by the flow rate and the total area.`] }),
  mc("m32", "8.4", "moderate", { stem: r`A plunger with an area of $4.0$ cm² pushes liquid through a syringe at a speed of $2.0$ cm/s. The liquid leaves through a needle opening with an area of $0.020$ cm².`, question: "What is the speed of the liquid as it leaves the needle?",
    choices: [n("4.0", "m/s"), sci("4.0", 2, "m/s"), sci("4.0", -2, "m/s"), sci("1.0", -4, "m/s")],
    why: [r`By continuity, $v_n = v_p A_p/A_n = (2.0\text{ cm/s})(4.0/0.020) = 400$ cm/s $= 4.0$ m/s.`, r`This leaves the result in cm/s, $400$, but labels it m/s. The conversion to m/s divides by $100$.`, r`This divides by $100$ twice when converting $400$ cm/s to m/s.`, r`This inverts the area ratio, $v_p A_n/A_p$. The liquid speeds up in the narrow needle.`] }),
  mc("m33", "8.4", "moderate", { stem: r`Water flows at $3.0$ m/s in a main pipe with a cross-sectional area of $8.0$ cm². The main pipe splits into two identical branch pipes, each with a cross-sectional area of $2.0$ cm². The water divides equally between the branches.`, question: "What is the speed of the water in each branch pipe?",
    choices: [n("6.0", "m/s"), n(12, "m/s"), n("3.0", "m/s"), n("1.5", "m/s")],
    why: [r`The flow rate in the main pipe is $A v = (8.0\text{ cm}^2)(3.0\text{ m/s}) = 24$ cm²·m/s. Each branch carries half, $12$, so $v = 12/2.0 = 6.0$ m/s.`, r`This assumes all of the water goes through one branch. The flow divides equally.`, r`This assumes the speed does not change. The branches have a smaller total area, $4.0$ cm², than the main pipe, $8.0$ cm², so the water speeds up.`, r`This halves the speed because the flow splits in two, but each branch is also narrower. The area changes by a factor of $4$.`] }),
  mc("m34", "8.4", "moderate", { stem: "Two ships sailing side by side in calm water, close together, are pushed toward each other.", question: "Which statement best explains this?",
    choices: ["Water moving faster between the ships has lower pressure than the water outside them.", "Water moving faster between the ships has higher pressure than the water outside them.", "Water moving more slowly between the ships has lower pressure than the water outside them.", "Water moving more slowly between the ships has higher pressure than the water outside them."],
    why: [r`Relative to the ships, the water in the narrow gap moves faster. By Bernoulli's principle its pressure is lower, so the higher pressure outside pushes the ships together.`, r`Faster flow means lower pressure, not higher. Higher pressure between the ships would push them apart.`, r`The water in the narrow gap moves faster, not slower. The lower pressure comes from the faster flow.`, r`This describes slower water and higher pressure between the ships. It would push the ships apart, not together.`] }),
  mc("m35", "8.4", "moderate", { stem: r`Two identical large open tanks are filled with water. In tank 1, water leaves through a small hole at a depth $h$ below the surface. In tank 2, water leaves through a small hole at a depth $4h$.`, question: r`What is the ratio $v_2/v_1$ of the speeds of the water leaving the holes?`,
    choices: [r`$2$`, r`$4$`, r`$16$`, r`$\dfrac{1}{2}$`],
    why: [r`By Bernoulli's equation with the surface speed approximately zero, $\tfrac12\rho v^2 = \rho g h$, so $v = \sqrt{2gh}$. With $4h$, $v_2/v_1 = \sqrt{4} = 2$.`, r`This makes the speed proportional to the depth. The speed is proportional to the square root of the depth.`, r`This makes the speed proportional to the square of the depth.`, r`This inverts the ratio. The deeper hole has the greater speed.`] }),
  mc("m36", "8.4", "difficult", { stem: r`Water leaves a nozzle pointing straight up with a fixed volume flow rate $Q$. The water rises to a maximum height $H$. The nozzle is replaced by one with half the exit area, and the volume flow rate is unchanged. Ignore air resistance.`, question: "What is the new maximum height of the water?",
    choices: [r`$4H$`, r`$2H$`, r`$16H$`, r`$\dfrac{H}{4}$`],
    why: [r`The exit speed is $v = Q/A$, so halving $A$ doubles $v$. The height is $v^2/2g$, so doubling $v$ multiplies the height by $4$.`, r`This makes the height proportional to the speed. The height is proportional to $v^2$.`, r`This treats the new nozzle as having half the diameter, which would quadruple the speed. The exit area is halved, not the diameter.`, r`This reverses the effect. A smaller exit area gives a greater speed and a greater height.`] }),
  mc("m37", "8.4", "difficult", { stem: r`A sealed tank holds water to a depth of $1.0$ m above a small hole in its side. The gas above the water has a gauge pressure of $4.0 \times 10^{4}$ Pa, and the speed of the water at the surface is approximately zero. Use $g = 10$ m/s² and $\rho = 1000$ kg/m³.`, question: "What is the speed of the water as it leaves the hole?",
    choices: [n(10, "m/s"), n("8.9", "m/s"), n("4.5", "m/s"), n("7.1", "m/s")],
    why: [r`Bernoulli's equation between the surface and the hole gives $P_g + \rho g h = \tfrac12\rho v^2$, so $v = \sqrt{2(P_g/\rho + gh)} = \sqrt{2(40 + 10)} = 10$ m/s.`, r`This leaves out the pressure of the water's depth, $\sqrt{2P_g/\rho}$.`, r`This leaves out the gas pressure, $\sqrt{2gh}$.`, r`This leaves out the factor of $2$ inside the square root, $\sqrt{P_g/\rho + gh}$.`] }),
  mc("m38", "8.4", "difficult", { stem: r`Water flows steadily up through a pipe that narrows. At the lower end the pipe has a cross-sectional area $A_1$, the water speed is $1.0$ m/s, and the gauge pressure is $3.0 \times 10^{5}$ Pa. At the upper end, which is $2.0$ m higher, the cross-sectional area is $A_1/4$. Use $\rho = 1000$ kg/m³ and $g = 9.8$ m/s².`, question: "What is the gauge pressure at the upper end?",
    choices: [sci("2.7", 5, "Pa"), sci("2.9", 5, "Pa"), sci("2.8", 5, "Pa"), sci("3.3", 5, "Pa")],
    why: [r`By continuity, $v_2 = 4.0$ m/s. By Bernoulli's equation, $P_2 = P_1 + \tfrac12\rho(v_1^2 - v_2^2) - \rho g\,\Delta y = 3.00 \times 10^{5} - 7500 - 19600 = 2.73 \times 10^{5}$ Pa.`, r`This accounts for the change in speed but leaves out the rise in height, which lowers the pressure by $\rho g \Delta y = 19600$ Pa.`, r`This accounts for the rise in height but leaves out the change in speed, which lowers the pressure by $7500$ Pa.`, r`This has the sign of both corrections wrong, adding $7500$ Pa and $19600$ Pa. The pressure falls both when the water speeds up and when it rises.`] }),
];

// ---- free response ----
const f = (id, topic, set, part, o) => ({ id: `p8r-${id}`, type: "frq", skill: "u8", topic, set, part, ...o });
const frq = [
  // EDA, 10 points
  f("f1a", "8.3", "p8r-s11", "(a)", { prompt: r`For Experiment 1, describe an experimental procedure the student can use to collect the data needed to determine $\rho$. Include the quantities that are measured and the equipment used to measure each.`,
    rows: [{ name: "Independent variable", earns: r`Identifies the total mass $m$ of the washers placed in the tube (or the number of washers, with the mass of one washer measured) as the quantity that is varied, and a balance to measure it.` },
      { name: "Dependent variable", earns: r`Identifies the length $d$ of the tube below the liquid surface as the quantity measured for each value of $m$, using a meter stick with the tube floating at rest.` }],
    solution: r`Place a measured mass $m$ of washers in the tube, using the balance, and let the tube float upright at rest. Read the length $d$ of the tube that is below the liquid surface with the meter stick. Repeat with at least five different values of $m$, and take the diameter of the tube with the calipers so that $A$ is known.` }),
  f("f1b", "8.3", "p8r-s11", "(b)", { prompt: r`Describe how the student can use the data to determine $\rho$. Include any additional measurement needed and the relationship from physics that is used.`,
    rows: [{ name: "Force balance", earns: r`States that the tube floats at rest, so the buoyant force equals the total weight: $\rho g A d = (M + m)g$.` },
      { name: "Slope", earns: r`States that a graph of $d$ versus $m$ is a straight line with a slope of $\dfrac{1}{\rho A}$, so $\rho = \dfrac{1}{A \cdot \text{slope}}$, with $A$ found from the diameter of the tube measured with the calipers.` }],
    solution: r`When the tube floats at rest, the net force on it is zero, so the buoyant force equals the weight of the tube and the washers: $\rho g A d = (M + m)g$. Solving, $d = \dfrac{1}{\rho A}\,m + \dfrac{M}{\rho A}$. A graph of $d$ versus $m$ is a straight line with a slope of $\dfrac{1}{\rho A}$. The student measures the diameter of the tube with the calipers to find $A = \pi D^2/4$, finds the slope of the best-fit line, and calculates $\rho = \dfrac{1}{A \cdot \text{slope}}$.` }),
  f("f1c", "8.4", "p8r-s11", "(c)(i)", { prompt: r`For Experiment 2, the student wants to determine $Q$ from the slope of a straight line. Describe which quantities should be plotted on the vertical and horizontal axes. State the relationship from physics that justifies the choice, and explain how the slope can be used to find $Q$.`,
    rows: [{ name: "Quantities", earns: r`Plots $v$ on one axis and $\dfrac{1}{d^2}$ on the other (either axis assignment is accepted if the slope analysis matches).` },
      { name: "Relationship", earns: r`Uses the continuity equation, $Q = Av$ with $A = \dfrac{\pi d^2}{4}$, to obtain $v = \dfrac{4Q}{\pi}\cdot\dfrac{1}{d^2}$.` },
      { name: "Slope", earns: r`States that the slope of $v$ versus $1/d^2$ is $\dfrac{4Q}{\pi}$, so $Q = \dfrac{\pi}{4}(\text{slope})$ (or $Q = \dfrac{\pi}{4\,(\text{slope})}$ if the axes are reversed).` }],
    solution: r`The same volume of water leaves the nozzle each second, $Q = Av$. For a circular nozzle $A = \pi d^2/4$, so $v = \dfrac{4Q}{\pi}\cdot\dfrac{1}{d^2}$. A graph of $v$ on the vertical axis and $1/d^2$ on the horizontal axis is a straight line through the origin with a slope of $\dfrac{4Q}{\pi}$. Then $Q = \dfrac{\pi}{4}(\text{slope})$.` }),
  f("f1d", "8.4", "p8r-s11", "(c)(ii)", { prompt: r`On the grid provided, plot the data in the form chosen in part (c)(i), and draw a straight line that best fits the data. Space is available for any calculated values.`,
    rows: [{ name: "Axes", earns: r`Labels both axes with the quantities and units, for example $v$ (m/s) and $1/d^2$ (cm$^{-2}$), and uses a linear scale that fills at least half of each axis.` },
      { name: "Points and line", earns: r`Plots all five points correctly and draws one straight best-fit line that passes near the origin (not a line connecting the points).` }],
    solution: r`The calculated values of $1/d^2$ in cm$^{-2}$ are $1.00$, $0.69$, $0.44$, $0.25$, and $0.16$. The graph has $1/d^2$ (cm$^{-2}$) on the horizontal axis, from $0$ to about $1.0$, and $v$ (m/s) on the vertical axis, from $0$ to about $4$. The five points, $(1.00, 3.8)$, $(0.69, 2.7)$, $(0.44, 1.7)$, $(0.25, 0.95)$, and $(0.16, 0.61)$, lie close to one straight line through the origin, and a single best-fit line is drawn through them.` }),
  f("f1e", "8.4", "p8r-s11", "(c)(iii)", { prompt: r`Use two points on your best-fit line, not data points, to calculate the slope, and use it to determine $Q$.`,
    rows: [{ name: "Value of Q", earns: r`Calculates the slope from two points on the line (about $3.8$ m·cm²/s) and obtains $Q = \dfrac{\pi}{4}(\text{slope})$ between $2.8 \times 10^{-4}$ and $3.2 \times 10^{-4}$ m³/s, converting cm² to m² and giving units.` }],
    solution: r`Two points on the line are $(0, 0)$ and $(1.00, 3.8)$, so the slope is $\dfrac{3.8 - 0}{1.00 - 0} = 3.8$ m·cm²/s $= 3.8 \times 10^{-4}$ m³/s, using $1\text{ cm}^2 = 10^{-4}\text{ m}^2$. Then $Q = \dfrac{\pi}{4}(3.8 \times 10^{-4}) = 3.0 \times 10^{-4}$ m³/s.` }),

  // QQT, 8 points
  f("f2a", "8.4", "p8r-s12", "(a)", { prompt: r`Is the speed $v_2$ of the water in the narrow section greater than, less than, or equal to $v_1$? Justify your answer with the continuity equation.`,
    rows: [{ name: "Claim", earns: r`States that $v_2$ is greater than $v_1$.` },
      { name: "Justification", earns: r`Uses the continuity equation, $A_1 v_1 = A_2 v_2$, and states that because $A_2 < A_1$, the speed must be greater in the narrow section for the same volume flow rate.` }],
    solution: r`$v_2$ is greater than $v_1$. The water is incompressible, so the same volume flows past each section per second: $A_1 v_1 = A_2 v_2$. Then $v_2 = v_1 A_1/A_2$, and because $A_2 < A_1$, $v_2 > v_1$.` }),
  f("f2b", "8.4", "p8r-s12", "(b)", { prompt: r`Derive an expression for the pressure difference $P_1 - P_2$ between the wide section and the narrow section, in terms of $\rho$, $v_1$, $A_1$, and $A_2$. Start from a fundamental principle.`,
    rows: [{ name: "Bernoulli's equation", earns: r`Writes Bernoulli's equation for the two sections of the horizontal pipe, $P_1 + \tfrac12\rho v_1^2 = P_2 + \tfrac12\rho v_2^2$, with no height terms because the pipe is horizontal.` },
      { name: "Continuity", earns: r`Substitutes $v_2 = v_1 A_1/A_2$ from the continuity equation.` },
      { name: "Expression", earns: r`Obtains $P_1 - P_2 = \tfrac12\rho v_1^2\left[\left(\dfrac{A_1}{A_2}\right)^2 - 1\right]$ (an equivalent expression is accepted).` }],
    solution: r`The pipe is horizontal, so Bernoulli's equation gives $P_1 + \tfrac12\rho v_1^2 = P_2 + \tfrac12\rho v_2^2$. Then $P_1 - P_2 = \tfrac12\rho(v_2^2 - v_1^2)$. With $v_2 = v_1 A_1/A_2$ from continuity, $P_1 - P_2 = \tfrac12\rho v_1^2\left[\left(\dfrac{A_1}{A_2}\right)^2 - 1\right]$.` }),
  f("f2c", "8.4", "p8r-s12", "(c)", { prompt: r`The pump is adjusted so that the speed $v_1$ in the wide section doubles. Does the difference $\Delta h$ between the water levels in the two tubes increase, decrease, or stay the same? If it changes, by what factor? Justify your answer.`,
    rows: [{ name: "Claim", earns: r`States that $\Delta h$ increases.` },
      { name: "Pressure and height", earns: r`States that the pressure difference between the two sections is supported by the difference in the water columns, $P_1 - P_2 = \rho g\,\Delta h$, so $\Delta h$ is proportional to $P_1 - P_2$.` },
      { name: "Factor", earns: r`Uses the result of part (b), $P_1 - P_2 \propto v_1^2$, to state that doubling $v_1$ multiplies $\Delta h$ by $4$.` }],
    solution: r`$\Delta h$ increases. The water in each tube is at rest and the tops of the tubes are open to the atmosphere, so the pressure difference between the two sections of the pipe equals the pressure of the extra water column: $P_1 - P_2 = \rho g\,\Delta h$. Then $\Delta h = \dfrac{v_1^2}{2g}\left[\left(\dfrac{A_1}{A_2}\right)^2 - 1\right]$, which is proportional to $v_1^2$. Doubling $v_1$ multiplies $\Delta h$ by $2^2 = 4$.` }),
];

export default [...mcq, ...frq];
